import{_ as n,a0 as a,w as i,s as d,I as l,x as p,a1 as o,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"LFTP : 一個功能強大的命令列FTP程序 | LCTT x X-CMD","titleTemplate":false,"description":"LFTP : 一個功能強大的命令列FTP程序 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFTP : 一個功能強大的命令列FTP程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFTP : 一個功能強大的命令列FTP程序 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150306 How to Setup lftp--A Simple Command line FTP Program","title":"LFTP : 一個功能強大的命令列FTP程序","tag":"201505","desc":""},"relativePath":"201505/20150306 How to Setup lftp--A Simple Command line FTP Program.md","filePath":"[post].md"}'),g={name:"201505/20150306 How to Setup lftp--A Simple Command line FTP Program.md"};function u(m,t,f,c,h,x){const e=a("Link");return i(),d("div",null,[t[16]||(t[16]=l("h1",{id:"lftp-一個功能強大的命令列ftp程序",tabindex:"-1"},[p("LFTP : 一個功能強大的命令列FTP程序 "),l("a",{class:"header-anchor",href:"#lftp-一個功能強大的命令列ftp程序","aria-label":"Permalink to “LFTP : 一個功能強大的命令列FTP程序”"},"​")],-1)),l("p",null,[t[1]||(t[1]=p("大家好，這篇文章是介紹Lftp以及如何在Linux操作系統下安裝的。",-1)),o(e,{href:"http://lftp.yar.ru/"},{default:r(()=>[...t[0]||(t[0]=[p("Lftp",-1)])]),_:1}),t[2]||(t[2]=p("是一個基於命令列的文件傳輸軟件（也被稱為FTP客户端），由Alexander Lukyanov開發並以GNU GPL協議許可發行。除了FTP協議外，它還支持FTPS，HTTP，HTTPS，HFTP，FISH，以及SFTP等協議。這個程序還支持FXP，允許數據繞過客户端直接在兩個FTP服務器之間傳輸。",-1))]),t[17]||(t[17]=s(`<p>它有很多很棒的高級功能，比如遞歸鏡像整個目錄樹以及斷點續傳下載。傳輸任務可以安排在稍後的時間段計劃執行，可以限制帶寬，可以創建傳輸列表，還支持類似Unix shell的任務控制。客户端還可以在交互式或自動腳本里使用。</p><h3 id="安裝lftp" tabindex="-1">安裝Lftp <a class="header-anchor" href="#安裝lftp" aria-label="Permalink to “安裝Lftp”">​</a></h3><p>在運行lftp之前，我們需要確定它已經正確安裝在我們的Linux發行版中了。下面是在常見Linux發行版中安裝lftp的一些命令。</p><p><strong>Ubuntu 14.04 LTS</strong></p><p>在Ubuntu 14.04 LTS以及它的衍生版中，我們可以通過apt管理程序安裝lftp。要安裝它，我們需要使用sudo權限在shell或終端裏運行下面的命令。</p><pre><code>$ sudo apt-get install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ubuntu-install-lftp.png" alt="ubuntu install lftp"></p><p><strong>CentOS/Fedora/RHEL</strong></p><p>因為在Fedora，CentOS和RHEL的軟件倉庫裏也能找到lftp，我們可以用<strong>yum</strong>管理程序來安裝它。</p><pre><code>$ sudo yum install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/fedora-lftp.png" alt="fedora lftp"></p><p><strong>Arch Linux</strong></p><p>在Arch Linux安裝包倉庫裏也有，我們可以簡單地使用pacman來安裝它。</p><pre><code>$ sudo pacman -S lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/archlinux-install-lftp.png" alt="archlinux install lftp"></p><p><strong>OpenSuse</strong></p><p>OpenSuse系統裏的包管理軟件Zypper可以用來安裝lftp。下面是在OpenSuse機器上用來安裝的命令。</p><pre><code>$ sudo zypper install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp_install.png" alt="opensuse lftp install"></p><h3 id="登錄" tabindex="-1">登錄 <a class="header-anchor" href="#登錄" aria-label="Permalink to “登錄”">​</a></h3><p>要登錄到ftp服務器或sftp服務器，我們首先需要知道所要求的認證信息，比如用户名，密碼，端口。</p><p>之後，我們可以通過lftp來登錄。</p><pre><code>$ lftp ftp://linoxide@localhost
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp-login.png" alt="ftp login"></p><p>如果需要指定登錄端口，我們可以按下面的方式加上去。</p><pre><code>$ lftp ftp://linoxide@localhost:21
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp-login-port.png" alt="ftp login with ports"></p><h3 id="導航" tabindex="-1">導航 <a class="header-anchor" href="#導航" aria-label="Permalink to “導航”">​</a></h3><p>我們可以用<strong>ls</strong>命令來列出文件和目錄，用<strong>cd</strong>命令進入到目錄。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ls-cd-lftp.png" alt="ls and cd"></p><h3 id="上傳和下載文件" tabindex="-1">上傳和下載文件 <a class="header-anchor" href="#上傳和下載文件" aria-label="Permalink to “上傳和下載文件”">​</a></h3><p>我們可以用<strong>pget</strong>命令來從遠端服務器下載文件。</p><pre><code>&gt; pget linspeed.svg
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pget-lftp.png" alt="pget lftp"></p><p>我們可以用<strong>put</strong>命令來上傳文件到遠端服務器。</p><pre><code>&gt; put linoxide.tar
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/put-upload.png" alt="upload with put"></p><p>要恢復之前只下載了一部分的文件/目錄，我們可以用-c開關：</p><pre><code>&gt; mirror -c Directory

&gt;pget -c linoxide.tar

&gt; put -c upload.tar
</code></pre><h3 id="使用鏡像命令" tabindex="-1">使用鏡像命令 <a class="header-anchor" href="#使用鏡像命令" aria-label="Permalink to “使用鏡像命令”">​</a></h3><p>我們可以用mirror命令來下載所指定的整個目錄。</p><pre><code>&gt; mirror remote local
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/mirror.png" alt="download with mirror"></p><p>還可以做反向鏡像(mirror -R)，可以用來上傳或更新本地目錄樹到服務器上。</p><pre><code>&gt; mirror -R local remote
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/mirror-reverse.png" alt="upload or update with mirror reverse"></p><p>要恢復之前下載了一部分的文件/目錄，我們可以用-c開關：</p><pre><code>&gt; mirror -c Directory
</code></pre><h3 id="下載隊列" tabindex="-1">下載隊列 <a class="header-anchor" href="#下載隊列" aria-label="Permalink to “下載隊列”">​</a></h3><p>我們可以在lftp裏使用queue的選項，這樣我們可以像基於GUI的客户端那樣挨個下載隊列裏選擇的文件。下面舉個例子。</p><p>為了避免隊列自動開始傳輸，我們可以這樣做：</p><pre><code>&gt; queue stop
</code></pre><p>現在，我們添加任務到隊列。</p><pre><code>&gt; queue mirror &quot;directory&quot;

&gt; queue pget &quot;file.tar&quot;
</code></pre><p>在建立好隊列後，我們再運行queue start命令。</p><pre><code>&gt; queue start
</code></pre><p>可以運行下面的命令移除整個隊列。</p><pre><code>&gt; queue -d
</code></pre><h3 id="分塊下載" tabindex="-1">分塊下載 <a class="header-anchor" href="#分塊下載" aria-label="Permalink to “分塊下載”">​</a></h3><p>下面是一個把一個文件分成3塊來下載的例子，你可以根據自己的需要調整。</p><p>使用pget命令分塊功能的方式是<strong>pget -n 3 file.tar</strong>，裏面的3是分塊的數目。</p><pre><code>&gt; pget -n 3 file.tar
</code></pre><p>使用mirror命令分塊功能的方式是<strong>mirror --use-pget-n=3 directory</strong>，裏面的3是分塊的數目。</p><pre><code>&gt; mirror --use-pget-n=3 linxoxide
</code></pre><p>我們可以用jobs -v命令來查看每個獨立分塊的下載速度以及整體速度。</p><h3 id="停止-繼續或刪除一次傳輸任務" tabindex="-1">停止，繼續或刪除一次傳輸任務 <a class="header-anchor" href="#停止-繼續或刪除一次傳輸任務" aria-label="Permalink to “停止，繼續或刪除一次傳輸任務”">​</a></h3><p>要取消傳輸我們可以按下Ctrl+C。而要恢復下載我們可以像下面那樣使用-c (--continue)開關。</p><pre><code>&gt; mirror -c directory
</code></pre><p>要刪除一次正在正在傳輸的任務我們可以用<strong>kill</strong>命令，而要刪除所有任務我們可以使用下面那樣的<strong>kill all</strong>命令。</p><pre><code>&gt; kill

&gt; kill all
</code></pre><h3 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h3><p>要從lftp退出，我們需要在終端或lftp交互接口中運行exit命令。</p><pre><code>&gt; exit
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>哇！我們已經成功地安裝了lftp並學會了它的一些基礎的主要使用方式。lftp是一個非常棒的命令列ftp客户端，它支持許多額外的功能以及很酷的特性。它比其他普通ftp客户端多了很多東西。好吧，你要是有任何問題，建議，反饋，請在下面的評論區裏留言。謝謝！享用lftp吧 😃</p><hr>`,76)),l("p",null,[t[4]||(t[4]=p("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/setup-lftp-command-line-ftp/"},{default:r(()=>[...t[3]||(t[3]=[p("http://linoxide.com/linux-how-to/setup-lftp-command-line-ftp/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=p("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:r(()=>[...t[5]||(t[5]=[p("Arun Pyasi",-1)])]),_:1}),t[9]||(t[9]=p(" 譯者：",-1)),o(e,{href:"https://github.com/zpl1025"},{default:r(()=>[...t[6]||(t[6]=[p("zpl1025",-1)])]),_:1}),t[10]||(t[10]=p(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[p("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=p("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[p("LCTT",-1)])]),_:1}),t[14]||(t[14]=p(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[p("Linux中國",-1)])]),_:1}),t[15]||(t[15]=p(" 榮譽推出",-1))])])}const L=n(g,[["render",u]]);export{b as __pageData,L as default};
